export async function exchangeCode(loginUrl: string, code: string, codeVerifier: string) {
  const res = await fetch(`${loginUrl}/services/oauth2/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "authorization_code",
      code,
      code_verifier: codeVerifier,
      client_id: process.env.SALESFORCE_CLIENT_ID!,
      client_secret: process.env.SALESFORCE_CLIENT_SECRET!,
      redirect_uri: process.env.SALESFORCE_REDIRECT_URI!,
    }),
  });
  const body = await res.json();
  if (!res.ok) throw new Error(`${body.error}: ${body.error_description}`);
  // body.instance_url is where ALL data API calls must go; body.id ends in /{orgId}/{userId}
  const [orgId, userId] = new URL(body.id).pathname.split("/").slice(-2);
  return { orgId, userId, instanceUrl: body.instance_url, accessToken: body.access_token, refreshToken: body.refresh_token };
}
